// Built-in @neondatabase/serverless HTTP driver shim for zero-build deployments
function neon(connectionString) {
  const cleanUrl = String(connectionString || '').trim().replace(/^["']+|["']+$/g, '');
  const parsed = new URL(cleanUrl);
  const endpoint = `https://${parsed.hostname}/sql`;

  async function queryFn(stringsOrQuery, ...values) {
    let query = '';
    let params = [];
    if (Array.isArray(stringsOrQuery)) {
      query = stringsOrQuery.reduce((acc, str, i) => acc + str + (i < values.length ? `$${i + 1}` : ''), '');
      params = values.map((v) => (v === undefined ? null : v));
    } else {
      query = String(stringsOrQuery);
      params = Array.isArray(values[0]) ? values[0].map((v) => (v === undefined ? null : v)) : [];
    }
    const res = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'Neon-Connection-String': cleanUrl,
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: JSON.stringify({ query, params })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.message || 'Neon SQL error');
    return data.rows || [];
  }
  queryFn.query = (q, p) => queryFn(q, p || []);
  return queryFn;
}
module.exports = { neon };
